CREATE COLUMN TABLE "TEST_AP"."WTQ10" ("DocEntry" INTEGER CS_INT NOT NULL , "LineSeq" INTEGER CS_INT NOT NULL , "AftLineNum" INTEGER CS_INT NOT NULL , "OrderNum" INTEGER CS_INT NOT NULL , "LineType" NVARCHAR(1), "LineText" NCLOB MEMORY THRESHOLD 1000, "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjType" NVARCHAR(20) DEFAULT '1250000001', PRIMARY KEY ("DocEntry", "LineSeq")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "WTQ10_SECONDARY" ON "TEST_AP"."WTQ10" ( "DocEntry" ASC, "AftLineNum" ASC, "OrderNum" ASC )